    "prompt": "<p>اصنع لعبة التقاط بسيطة بنقاط وفوز:</p>\n<ol><li><code dir=\"ltr\">this.score = 0</code>، وسفينة <code dir=\"ltr\">this.ship</code> (فيزيائية) عند (40, 160) تتحرك يميناً بسرعة 200.</li><li>مجموعة عملات <code dir=\"ltr\">this.coins</code> فيزيائية: 6 عملات من (100, 160) بمسافة 60 أفقياً (<code dir=\"ltr\">repeat: 5</code>).</li><li><code dir=\"ltr\">overlap</code> بين السفينة والعملات: أخفِ العملة بـ <code dir=\"ltr\">disableBody(true, true)</code> وزِد النقاط 5.</li><li>عندما يصبح عدد العملات الفعالة 0 انتقل لمشهد <code dir=\"ltr\">&quot;win&quot;</code> مع تمرير النقاط، ومشهد <code dir=\"ltr\">Win</code> (مفتاحه <code dir=\"ltr\">&quot;win&quot;</code>) يحفظ <code dir=\"ltr\">this.final = data.score</code> في <code dir=\"ltr\">create(data)</code>.</li></ol>",
    "starter": "class Main extends Phaser.Scene {\n  constructor() { super(\"main\"); }\n  preload() {\n    this.load.image(\"ship\", \"assets/ship.png\");\n    this.load.image(\"coin\", \"assets/coin.png\");\n  }\n  create() {\n  }\n}\nnew Phaser.Game({ type: Phaser.AUTO, width: 480, height: 320, physics: { default: \"arcade\" }, scene: [Main] });",
    "solution": "class Main extends Phaser.Scene {\n  constructor() { super(\"main\"); }\n  preload() {\n    this.load.image(\"ship\", \"assets/ship.png\");\n    this.load.image(\"coin\", \"assets/coin.png\");\n  }\n  create() {\n    this.score = 0;\n    this.ship = this.physics.add.image(40, 160, \"ship\").setVelocityX(200);\n    this.coins = this.physics.add.group({ key: \"coin\", repeat: 5, setXY: { x: 100, y: 160, stepX: 60 } });\n    this.physics.add.overlap(this.ship, this.coins, (ship, coin) => {\n      coin.disableBody(true, true);\n      this.score += 5;\n      if (this.coins.countActive(true) === 0) this.scene.start(\"win\", { score: this.score });\n    });\n  }\n}\nclass Win extends Phaser.Scene {\n  constructor() { super(\"win\"); }\n  create(data) {\n    this.final = data.score;\n    this.add.text(240, 160, \"YOU WIN!\", { fontSize: \"32px\" }).setOrigin(0.5);\n  }\n}\nnew Phaser.Game({ type: Phaser.AUTO, width: 480, height: 320, physics: { default: \"arcade\" }, scene: [Main, Win] });",
